commands.windows:
# Standalone example: Package names and versions as text. macOS lists application bundle paths only; Windows reads machine-wide uninstall registry entries.
$ErrorActionPreference = "Stop"
Get-ItemProperty 'HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*','HKLM:\Software\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*' -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName } | ForEach-Object { '{0} {1}' -f $_.DisplayName, $_.DisplayVersion }
